import Nav from './Nav';
import React from 'react';
import '../assets/css/Header.scss';
function Header() {
    return (
        <>
            <div className="topBanner">
                지금 가입하고 <b>최대 1만 2천원 할인 쿠폰</b>  받아가세요!
            </div>
            <div className="headerInner">
                <div className="headerLogo">
                    <h1>
                        <img src={require('../assets/images/kully_logo.svg').default} alt="Kully Logo" />
                    </h1>
                    <button className="market">마켓컬리</button>|<button className="beauty">뷰티컬리</button>
                </div>
                <div className="searchForm">
                    <input type="text" id="searchBox" className="searchBox" placeholder="검색어를 입력해 주세요."/>
                    <img src={require('../assets/images/searchIcon.svg').default} alt="Search Icon" className="searchIcon"/>
                </div>
                <div className="memberDiv">
                    <img src={require('../assets/images/position.svg').default} alt=""/>
                    <img src={require('../assets/images/fav.svg').default} alt=""/>
                    <img src={require('../assets/images/cart.svg').default} alt=""/>
                </div>

                <div className="memberMenu">회원가입 로그인 고객센터</div>
            </div>
            <div className="headerNav">
                <Nav/>
            </div>
        </>
    );
}

export default Header;